CREATE OR REPLACE FUNCTION private.gridex_require_locked_pricing_run_for_invoice_export()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
begin
  if not exists (
    select 1
    from public.pricing_runs pr
    where pr.id = new.pricing_run_id
      and pr.company_id = new.company_id
      and pr.status = 'locked'
  ) then
    raise exception using
      errcode = '23514',
      message = 'invoice_export_requires_locked_pricing_run';
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.ensure_customer_invoice_reference_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
begin
  if tg_op = 'UPDATE'
     and new.company_id is not distinct from old.company_id
     and new.id is not distinct from old.id then
    new.invoice_reference := old.invoice_reference;
    return new;
  end if;
  new.invoice_reference := 'invoice_' || substr(
    translate(
      rtrim(encode(extensions.digest(convert_to(
        'gridex-public-reference:v1:' || new.company_id::text || ':invoice:' || new.id::text,
        'UTF8'
      ), 'sha256'::text), 'base64'), '='),
      '+/', '-_'
    ),
    1,
    32
  );
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_assert_company_operational_for_write()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
declare
  v_company_status text;
begin
  if new.company_id is null then
    return new;
  end if;

  select status into v_company_status
  from public.companies
  where id = new.company_id;

  if coalesce(v_company_status, 'active') not in ('active', 'onboarding') then
    raise exception 'Tenant % is %, write is blocked for operational data', new.company_id, v_company_status
      using errcode = 'P0001';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_audit_critical_row_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
      declare
        v_old jsonb := case when TG_OP in ('UPDATE','DELETE') then to_jsonb(OLD) else null end;
        v_new jsonb := case when TG_OP in ('INSERT','UPDATE') then to_jsonb(NEW) else null end;
        v_company_id uuid := null;
        v_actor uuid := null;
        v_entity_id text := null;
      begin
        if TG_TABLE_NAME = 'audit_logs' then
          return coalesce(NEW, OLD);
        end if;

        v_company_id := nullif(coalesce(v_new ->> 'company_id', v_old ->> 'company_id'), '')::uuid;
        if v_company_id is null and TG_TABLE_NAME = 'companies' then
          v_company_id := nullif(coalesce(v_new ->> 'id', v_old ->> 'id'), '')::uuid;
        end if;

        v_actor := nullif(coalesce(
          v_new ->> 'updated_by',
          v_new ->> 'created_by',
          v_new ->> 'actor_user_id',
          v_new ->> 'invited_by',
          v_new ->> 'paused_by',
          v_old ->> 'updated_by',
          v_old ->> 'created_by',
          v_old ->> 'actor_user_id',
          v_old ->> 'invited_by',
          v_old ->> 'paused_by'
        ), '')::uuid;

        v_entity_id := coalesce(v_new ->> 'id', v_old ->> 'id');

        insert into public.audit_logs (
          company_id,
          actor_user_id,
          entity_type,
          entity_id,
          action,
          old_values,
          new_values,
          metadata
        ) values (
          v_company_id,
          v_actor,
          TG_TABLE_NAME,
          v_entity_id,
          lower(TG_TABLE_NAME || '_' || TG_OP),
          v_old,
          v_new,
          jsonb_build_object(
            'source', 'gridex_audit_critical_row_change',
            'operation', TG_OP,
            'table', TG_TABLE_NAME
          )
        );

        return coalesce(NEW, OLD);
      end;
      $function$

CREATE OR REPLACE FUNCTION public.gridex_billing_underlays_company_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  parent_company_id uuid;
begin
  if new.customer_id is not null and to_regclass('public.customers') is not null then
    select company_id into parent_company_id from public.customers where id = new.customer_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'customer_id');
  end if;
  if new.customer_contract_id is not null and to_regclass('public.customer_contracts') is not null then
    select company_id into parent_company_id from public.customer_contracts where id = new.customer_contract_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'customer_contract_id');
  elsif new.contract_id is not null and to_regclass('public.customer_contracts') is not null then
    select company_id into parent_company_id from public.customer_contracts where id = new.contract_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'contract_id');
  end if;
  if new.site_id is not null and to_regclass('public.customer_sites') is not null then
    select company_id into parent_company_id from public.customer_sites where id = new.site_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'site_id');
  end if;
  if new.metering_point_id is not null and to_regclass('public.metering_points') is not null then
    select company_id into parent_company_id from public.metering_points where id = new.metering_point_id;
    perform public.gridex_assert_same_company(new.company_id, parent_company_id, TG_TABLE_NAME, 'metering_point_id');
  end if;
  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_billing_underlay_price_area()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_contract_id uuid := coalesce(new.contract_id, new.customer_contract_id);
  v_contract_snapshot_id uuid;
  v_contract_area text;
  v_snapshot_area text;
  v_legacy_snapshot_area text;
  v_metadata_area text;
  v_canonical_area text;
begin
  if v_contract_id is null then
    return new;
  end if;

  select
    c.contract_price_snapshot_id,
    upper(nullif(btrim(c.price_area_used), '')),
    upper(nullif(btrim(c.price_snapshot #>> '{snapshot_json,price_area}'), '')),
    upper(nullif(btrim(c.metadata ->> 'selected_price_area'), ''))
  into
    v_contract_snapshot_id,
    v_contract_area,
    v_legacy_snapshot_area,
    v_metadata_area
  from public.customer_contracts c
  where c.id = v_contract_id
    and c.company_id = new.company_id;

  if not found then
    return new;
  end if;

  select upper(nullif(btrim(s.snapshot_json ->> 'price_area'), ''))
  into v_snapshot_area
  from public.contract_price_snapshots s
  where s.id = coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id)
    and s.contract_id = v_contract_id
    and s.company_id = new.company_id;

  v_canonical_area := coalesce(
    case when v_snapshot_area in ('SE1','SE2','SE3','SE4') then v_snapshot_area end,
    case when v_contract_area in ('SE1','SE2','SE3','SE4') then v_contract_area end,
    case when v_legacy_snapshot_area in ('SE1','SE2','SE3','SE4') then v_legacy_snapshot_area end,
    case when v_metadata_area in ('SE1','SE2','SE3','SE4') then v_metadata_area end
  );

  if coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id) is not null
     and v_canonical_area is null then
    raise exception 'billing_contract_price_area_missing'
      using errcode = '23514',
            detail = jsonb_build_object(
              'billing_underlay_id', new.id,
              'contract_id', v_contract_id,
              'contract_price_snapshot_id', coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id)
            )::text;
  end if;

  if v_canonical_area is null then
    return new;
  end if;

  if new.price_area is null or nullif(btrim(new.price_area), '') is null then
    new.price_area := v_canonical_area;
  elsif upper(btrim(new.price_area)) <> v_canonical_area then
    raise exception 'billing_underlay_price_area_mismatch'
      using errcode = '23514',
            detail = jsonb_build_object(
              'billing_underlay_id', new.id,
              'contract_id', v_contract_id,
              'submitted_price_area', upper(btrim(new.price_area)),
              'canonical_price_area', v_canonical_area,
              'contract_price_snapshot_id', coalesce(new.contract_price_snapshot_id, v_contract_snapshot_id)
            )::text;
  else
    new.price_area := v_canonical_area;
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_enforce_customer_contract_chain_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_row jsonb:=to_jsonb(new);
  v_company_id uuid:=nullif(v_row->>'company_id','')::uuid;
  v_customer_id uuid:=nullif(v_row->>'customer_id','')::uuid;
  v_contract_id uuid:=coalesce(
    nullif(v_row->>'customer_contract_id','')::uuid,
    nullif(v_row->>'contract_id','')::uuid
  );
  v_metering_point_id uuid:=nullif(v_row->>'metering_point_id','')::uuid;
  v_underlay_id uuid:=nullif(v_row->>'billing_underlay_id','')::uuid;
  v_export_item_id uuid:=coalesce(
    nullif(v_row->>'invoice_export_item_id','')::uuid,
    nullif(v_row->>'canonical_export_item_id','')::uuid
  );
begin
  if v_company_id is null or v_customer_id is null then
    raise exception using errcode='23502',message='customer_chain_company_customer_required';
  end if;
  if v_contract_id is not null and not exists(
    select 1 from public.customer_contracts cc
    where cc.id=v_contract_id
      and cc.company_id=v_company_id
      and cc.customer_id=v_customer_id
  ) then
    raise exception using errcode='23514',message='customer_chain_contract_mismatch';
  end if;
  if v_metering_point_id is not null and not exists(
    select 1 from public.metering_points mp
    where mp.id=v_metering_point_id
      and mp.company_id=v_company_id
      and mp.customer_id=v_customer_id
  ) then
    raise exception using errcode='23514',message='customer_chain_metering_point_mismatch';
  end if;
  if v_underlay_id is not null and not exists(
    select 1 from public.billing_underlays bu
    where bu.id=v_underlay_id
      and bu.company_id=v_company_id
      and bu.customer_id=v_customer_id
      and (
        v_contract_id is null
        or coalesce(bu.customer_contract_id,bu.contract_id)=v_contract_id
      )
  ) then
    raise exception using errcode='23514',message='customer_chain_underlay_mismatch';
  end if;
  if v_export_item_id is not null and not exists(
    select 1 from public.invoice_export_items iei
    where iei.id=v_export_item_id
      and iei.company_id=v_company_id
      and iei.customer_id=v_customer_id
      and (
        v_contract_id is null
        or iei.customer_contract_id=v_contract_id
      )
  ) then
    raise exception using errcode='23514',message='customer_chain_export_item_mismatch';
  end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_guard_portfolio_settlement_immutability()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if tg_op='DELETE' then raise exception using errcode='55000',message='portfolio_settlement_append_only'; end if;
  if old.status<>new.status and not (
    (old.status='draft' and new.status='calculated')
    or (old.status='calculated' and new.status='reviewed')
    or (old.status='reviewed' and new.status='final')
    or (old.status='final' and new.status='locked')
  ) then
    raise exception using errcode='23514',message='invalid_portfolio_settlement_transition';
  end if;
  if new.status in('final','locked') and (
    new.portfolio_price_ore_per_kwh is null
    or new.calculation_snapshot_sha256 is null
    or new.calculated_at is null or new.reviewed_at is null or new.approved_at is null
  ) then
    raise exception using errcode='23514',message='portfolio_settlement_final_evidence_incomplete';
  end if;
  if old.status='locked' and not (
    coalesce(current_setting('gridex.portfolio_correction_write',true),'')='on'
    and new.is_current=false and new.superseded_by_settlement_id is not null
    and (to_jsonb(new)-'is_current'-'superseded_by_settlement_id')=(to_jsonb(old)-'is_current'-'superseded_by_settlement_id')
  ) then
    raise exception using errcode='55000',message='locked_portfolio_settlement_immutable';
  end if;
  if old.status='final' and not (
    (
      new.status='locked'
      and (to_jsonb(new)-'status'-'locked_by'-'locked_at')
        =(to_jsonb(old)-'status'-'locked_by'-'locked_at')
    ) or (
      coalesce(current_setting('gridex.portfolio_correction_write',true),'')='on'
      and new.status='final' and new.is_current=false
      and new.superseded_by_settlement_id is not null
      and (to_jsonb(new)-'is_current'-'superseded_by_settlement_id')
        =(to_jsonb(old)-'is_current'-'superseded_by_settlement_id')
    )
  ) then
    raise exception using errcode='55000',message='final_portfolio_settlement_immutable_create_correction_revision';
  end if;
  return new;
end $function$

CREATE OR REPLACE FUNCTION public.gridex_normalize_audit_context_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  v_headers jsonb:='{}'::jsonb;
  v_raw_headers text:=nullif(current_setting('request.headers',true),'');
begin
  if v_raw_headers is not null then
    begin
      v_headers:=v_raw_headers::jsonb;
    exception when others then
      v_headers:='{}'::jsonb;
    end;
  end if;

  new.actor_type:=coalesce(
    nullif(new.actor_type,''),
    case when new.actor_user_id is null then 'system' else 'user' end
  );
  if new.actor_user_id is null then
    new.system_actor:=coalesce(
      nullif(new.system_actor,''),
      nullif(new.metadata->>'system_actor',''),
      'unspecified_system_actor'
    );
  else
    new.system_actor:=null;
  end if;

  new.request_id:=coalesce(
    nullif(new.request_id,''),
    nullif(new.metadata->>'request_id',''),
    nullif(v_headers->>'x-request-id',''),
    gen_random_uuid()::text
  );
  new.correlation_id:=coalesce(
    nullif(new.correlation_id,''),
    nullif(new.metadata->>'correlation_id',''),
    nullif(v_headers->>'x-correlation-id',''),
    new.request_id
  );
  new.resource_type:=coalesce(nullif(new.resource_type,''),new.entity_type);
  new.resource_id:=coalesce(nullif(new.resource_id,''),new.entity_id);
  new.previous_status:=coalesce(
    nullif(new.previous_status,''),
    nullif(new.old_values->>'lifecycle_status',''),
    nullif(new.old_values->>'status','')
  );
  new.new_status:=coalesce(
    nullif(new.new_status,''),
    nullif(new.new_values->>'lifecycle_status',''),
    nullif(new.new_values->>'status','')
  );
  new.metadata:=coalesce(new.metadata,'{}'::jsonb)||jsonb_strip_nulls(jsonb_build_object(
    'actor_type',new.actor_type,
    'system_actor',new.system_actor,
    'request_id',new.request_id,
    'correlation_id',new.correlation_id,
    'resource_type',new.resource_type,
    'resource_id',new.resource_id,
    'previous_status',new.previous_status,
    'new_status',new.new_status
  ));
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_partner_exports_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
begin
  perform public.gridex_validate_partner_export_payload(
    new.export_kind,
    coalesce(new.payload, '{}'::jsonb)
  );

  if new.status = 'acknowledged' and new.sent_at is null then
    raise exception 'Cannot acknowledge partner export before sent_at is set';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_partner_exports_status_guard_2()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
begin
  if new.status = 'acknowledged' and new.sent_at is null then
    raise exception 'Cannot acknowledge partner export before sent_at is set';
  end if;

  if new.status = 'sent' and new.queued_at is null then
    raise exception 'Cannot send partner export before queued_at is set';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_protect_locked_pricing_runs()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if coalesce(current_setting('app.gridex_pricing_maintenance', true), '') = 'on' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  if tg_op = 'DELETE' then
    if old.status = 'locked' then
      raise exception 'Locked pricing runs cannot be deleted. Unlock the billing period and use the explicit maintenance path.'
        using errcode = 'P0001';
    end if;
    return old;
  end if;

  if old.status = 'locked' then
    raise exception 'Locked pricing runs are immutable. Unlock the billing period via the explicit maintenance path before changing run %.', old.id
      using errcode = 'P0001';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_protect_sent_invoice_export_items()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  protected boolean;
begin
  if coalesce(current_setting('app.gridex_billing_maintenance', true), '') = 'on' then
    if tg_op = 'DELETE' then
      return old;
    end if;
    return new;
  end if;

  protected := old.status in ('sent', 'credited');

  if tg_op = 'DELETE' then
    if protected then
      raise exception 'Skickade/krediterade fakturaexportposter kan inte raderas (item %). Skapa kredit eller korrigering i stället.', old.id
        using errcode = 'P0001';
    end if;
    return old;
  end if;

  if not protected then
    return new;
  end if;

  -- Block re-send: status must never go back to a sendable state.
  if new.status in ('pending', 'failed', 'failed_retryable') then
    raise exception 'Fakturaexportpost % är redan skickad och kan inte skickas om. Skapa kredit eller korrigering i stället.', old.id
      using errcode = 'P0001';
  end if;

  -- Block financial mutation of a sent invoice.
  if new.amount_ex_vat is distinct from old.amount_ex_vat
     or new.vat_amount is distinct from old.vat_amount
     or new.amount_inc_vat is distinct from old.amount_inc_vat
     or new.rounding_amount is distinct from old.rounding_amount
     or new.request_payload is distinct from old.request_payload
     or new.idempotency_key is distinct from old.idempotency_key
     or new.pricing_run_id is distinct from old.pricing_run_id
     or new.billing_underlay_id is distinct from old.billing_underlay_id
     or new.customer_id is distinct from old.customer_id
  then
    raise exception 'Fakturaexportpost % är skickad och får inte ändras finansiellt. Skapa kredit eller korrigering i stället.', old.id
      using errcode = 'P0001';
  end if;

  -- Provider invoice identity may be set once but never rewritten.
  if old.provider_invoice_guid is not null
     and new.provider_invoice_guid is distinct from old.provider_invoice_guid
  then
    raise exception 'Fakturaexportpost % har redan ett leverantörs-id och det får inte skrivas om.', old.id
      using errcode = 'P0001';
  end if;

  return new;
end;
$function$

CREATE OR REPLACE FUNCTION public.gridex_public_catalog_dependency_revision_trigger_v1()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog', 'pg_temp'
AS $function$
declare
  v_row jsonb := case when tg_op='DELETE' then to_jsonb(old) else to_jsonb(new) end;
  v_company_id uuid;
  v_entity_id text := v_row->>'id';
begin
  case tg_table_name
    when 'companies' then v_company_id := (v_row->>'id')::uuid;
    when 'tenant_contract_assignments' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_offers' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_products' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'contract_product_versions' then
      select cp.company_id into v_company_id from public.contract_products cp where cp.id = nullif(v_row->>'contract_product_id','')::uuid;
    when 'legal_bundle_versions' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'legal_bundle_version_documents' then
      select lb.company_id into v_company_id from public.legal_bundle_versions lb where lb.id = nullif(v_row->>'legal_bundle_version_id','')::uuid;
    when 'tenant_legal_profiles' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_plans' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_plan_versions' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'price_books' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'integration_api_clients' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'portfolios' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    when 'portfolio_monthly_settlements' then v_company_id := nullif(v_row->>'company_id','')::uuid;
    else v_company_id := null;
  end case;
  if v_company_id is not null then
    perform public.gridex_bump_contract_publication_revision(v_company_id,'website',tg_table_name || '.' || lower(tg_op),v_entity_id);
    perform public.gridex_bump_contract_publication_revision(v_company_id,'api',tg_table_name || '.' || lower(tg_op),v_entity_id);
  end if;
  if tg_op='DELETE' then return old; end if;
  return new;
end
$function$

CREATE OR REPLACE FUNCTION public.gridex_sync_portfolio_monthly_prices_for_version(p_price_plan_version_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_version record; v_row jsonb; v_month text; v_area text; v_amount numeric; v_existing_id uuid; v_existing_price numeric; v_existing_locked timestamptz; v_status text;
begin
  select * into v_version from public.price_plan_versions where id=p_price_plan_version_id;
  if v_version.id is null then raise exception 'price_plan_version_missing'; end if;
  if jsonb_typeof(coalesce(v_version.snapshot_json,'{}'::jsonb)->'portfolio_monthly_prices') is distinct from 'array' then return; end if;
  v_status:=case when v_version.status in ('published','active','approved') and v_version.locked_at is not null then 'published' else 'draft' end;
  for v_row in select value from jsonb_array_elements(v_version.snapshot_json->'portfolio_monthly_prices') loop
    v_month:=left(coalesce(v_row->>'period_month',v_row->>'billing_month',''),7);
    v_area:=upper(coalesce(v_row->>'price_area_code',v_row->>'price_area',''));
    v_amount:=nullif(coalesce(v_row->>'amount_ore_per_kwh',v_row->>'amount'),'')::numeric;
    if v_month !~ '^\d{4}-\d{2}$' or v_area not in ('SE1','SE2','SE3','SE4') or v_amount is null then
      raise exception 'invalid_portfolio_monthly_price_snapshot';
    end if;
    v_existing_id:=null; v_existing_price:=null; v_existing_locked:=null;
    select id,price_ex_vat_sek_per_kwh,locked_at into v_existing_id,v_existing_price,v_existing_locked
    from public.portfolio_monthly_prices
      where price_plan_version_id=v_version.id and price_area=v_area and billing_month=v_month
        and superseded_at is null and status<>'superseded' limit 1;
    if v_existing_id is not null then
      if v_existing_locked is not null then
        if abs(v_existing_price-(v_amount/100))>0.00000001 then
          raise exception 'locked_portfolio_monthly_price_snapshot_mismatch';
        end if;
      else
        update public.portfolio_monthly_prices set
          price_plan_id=v_version.price_plan_id,price_ex_vat_sek_per_kwh=v_amount/100,
          status=v_status,source='contract_price_version',approved_at=case when v_status='published' then coalesce(v_version.approved_at,now()) end,
          confirmed_at=case when v_status='published' then coalesce(v_version.approved_at,now()) end,
          published_at=case when v_status='published' then coalesce(v_version.published_at,now()) end,
          locked_at=case when v_status='published' then coalesce(v_version.locked_at,now()) end,
          calculation_snapshot=jsonb_build_object('amount_ore_per_kwh',v_amount,'unit','ore_per_kwh','vat_included',false,'price_plan_version_id',v_version.id),updated_at=now()
        where id=v_existing_id;
      end if;
    else
      insert into public.portfolio_monthly_prices(
        company_id,price_plan_id,price_plan_version_id,price_area,billing_month,price_ex_vat_sek_per_kwh,currency,status,source,notes,version_number,
        approved_at,confirmed_at,published_at,locked_at,calculation_snapshot,created_by,updated_by
      ) values(
        v_version.company_id,v_version.price_plan_id,v_version.id,v_area,v_month,v_amount/100,'SEK',v_status,'contract_price_version',
        'Materialiserad från låst price_plan_version.snapshot_json',coalesce(v_version.version_number,1),
        case when v_status='published' then coalesce(v_version.approved_at,now()) end,case when v_status='published' then coalesce(v_version.approved_at,now()) end,
        case when v_status='published' then coalesce(v_version.published_at,now()) end,case when v_status='published' then coalesce(v_version.locked_at,now()) end,
        jsonb_build_object('amount_ore_per_kwh',v_amount,'unit','ore_per_kwh','vat_included',false,'price_plan_version_id',v_version.id),v_version.created_by,v_version.created_by
      );
    end if;
  end loop;
end $function$

CREATE OR REPLACE FUNCTION public.set_updated_at_timestamp()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'auth', 'extensions'
AS $function$
begin
  new.updated_at = now();
  return new;
end;
